-- ============================================================
-- spell_proc: let the per-rank DBC ProcChance drive Wailing Souls
-- ============================================================
-- Chance = 0 makes SpellMgr fall back to spellInfo->ProcChance, and that
-- fallback is evaluated per rank inside the chain loop (SpellMgr.cpp:2083) --
-- so ranks keep their individual 34/67/100 while the tooltip ($h) reads the
-- same field. One source of truth instead of two that can drift.
-- ABS() is required: a negative id row would otherwise survive and win.
DELETE FROM `spell_proc` WHERE ABS(`SpellId`) IN (30299, 30301, 30302);
INSERT INTO `spell_proc` (`SpellId`, `SchoolMask`, `SpellFamilyName`, `SpellFamilyMask0`, `SpellFamilyMask1`, `SpellFamilyMask2`, `ProcFlags`, `SpellTypeMask`, `SpellPhaseMask`, `HitMask`, `AttributesMask`, `DisableEffectsMask`, `ProcsPerMinute`, `Chance`, `Cooldown`, `Charges`) VALUES
(30299, 0, 5, 256, 0, 0, 65536, 1, 2, 0, 0, 0, 0, 0, 0, 0),
(30301, 0, 5, 256, 0, 0, 65536, 1, 2, 0, 0, 0, 0, 0, 0, 0),
(30302, 0, 5, 256, 0, 0, 65536, 1, 2, 0, 0, 0, 0, 0, 0, 0);


